def normalize(obj):
 if isinstance(obj,str):return obj.replace(chr(92)*2,chr(92))
 if isinstance(obj,list):return [normalize(x) for x in obj]
 if isinstance(obj,dict):return {k:normalize(v) for k,v in obj.items()}
 return obj

def read(p):return json.loads(p.read_text())
COMPACT_FILES={'data/conclusions/english.json', 'data/textbook.json', 'data/conclusions/math.json', 'data/conclusions/geography.json', 'data/conclusions/chinese.json', 'data/conclusions/history.json', 'data/conclusions/politics.json'}
def write(p,obj):p.write_text((json.dumps(obj,ensure_ascii=False,separators=(',',':')) if str(p.relative_to(ROOT)) in COMPACT_FILES else json.dumps(obj,ensure_ascii=False,indent=2))+'\n')
