   ks.append(k)
   question=Q[sid][next(i for i,q in enumerate(Q[sid]) if q[0]==j)]
   cs.append({'id':cids[j],'subject':sid,'kpIds':[kids[j]],'title':title+'：条件化提要','statement':points[0]+' '+points[1],'conditions':cond,'derivation':proof,'example':{'q':question[2]+('\n'+'；'.join(chr(65+i)+'. '+o for i,o in enumerate(question[3])) if question[3] else ''),'a':question[4]+('：'+question[3][ord(question[4])-65] if question[1]=='single' else '')+'。解析：'+'；'.join(question[5])},'pitfalls':pitfalls,'freq':'mid','sectionIds':[section],'provenance':scopedmeta})
   for field,ident in [('kpIds',kids[j]),('conclIds',cids[j])]:
    sec[section].setdefault(field,[])
